def save_existing_favorites(apps, schema_editor):
    """Los favoritos que ya existían también quedan guardados (favoritos ⊂ guardados)."""
    Favorito = apps.get_model("api", "Favorito")
    TaskSave = apps.get_model("api", "TaskSave")
    saves = [
        TaskSave(user_id=user_id, task_id=task_id)
        for user_id, task_id in Favorito.objects.values_list("user_id", "task_id").iterator()
    ]
    TaskSave.objects.bulk_create(saves, batch_size=500, ignore_conflicts=True)
    # `created_at` (auto_now_add) queda con la fecha de la migración: se copia la del favorito.
    TaskSave.objects.update(created_at=Subquery(
        Favorito.objects.filter(user_id=OuterRef("user_id"), task_id=OuterRef("task_id")).values("created_at")[:1]
    ))


